import * as vscode from 'vscode';
// Removed fs and path imports for web compatibility

// Spell data interface matching both SRD API and XML formats
export interface Spell {
    name: string;
    level: number;
    school: string;
    castingTime: string;
    range: string;
    components: string;
    duration: string;
    description: string;
    higherLevels?: string;
    classes: string[];
    ritual: boolean;
    concentration: boolean;
    source: string;
    damage?: {
        type: string;
        dice: { [level: number]: string };
    };
}

export interface Monster {
    name: string;
    size: string;
    type: string;
    subtype?: string;
    alignment: string;
    ac: number;
    acType?: string;
    hp: number;
    hitDice: string;
    speed: string;
    stats: {
        str: number;
        dex: number;
        con: number;
        int: number;
        wis: number;
        cha: number;
    };
    saves?: string[];
    skills?: string[];
    damageVulnerabilities?: string[];
    damageResistances?: string[];
    damageImmunities?: string[];
    conditionImmunities?: string[];
    senses: string;
    languages: string;
    cr: string;
    xp: number;
    proficiencyBonus: number;
    traits?: Array<{ name: string; description: string }>;
    actions?: Array<{ name: string; description: string }>;
    reactions?: Array<{ name: string; description: string }>;
    legendaryActions?: Array<{ name: string; description: string }>;
    legendaryDescription?: string;
    description?: string;
    source: string;
}

export interface Item {
    name: string;
    type: string;
    subtype?: string;
    rarity: string;
    magic: boolean;
    attunement: boolean;
    attunementRequirement?: string;
    weight: number;
    value: string;
    damage?: {
        dice: string;
        type: string;
        twoHanded?: string;
    };
    armorClass?: {
        base: number;
        dexBonus: boolean;
        maxBonus?: number;
    };
    stealthDisadvantage?: boolean;
    strengthRequirement?: number;
    properties: string[];
    range?: {
        normal: number;
        long?: number;
    };
    description: string;
    source: string;
}

/**
 * Search result for compendium entries (used by editors for autocomplete/previews)
 */
export interface CompendiumSearchResult {
    type: 'spell' | 'monster' | 'item';
    name: string;
    subtitle: string;
    isCustom?: boolean;
}

// School abbreviation mapping
const SCHOOL_MAP: { [key: string]: string } = {
    'A': 'Abjuration',
    'C': 'Conjuration',
    'D': 'Divination',
    'EN': 'Enchantment',
    'EV': 'Evocation',
    'I': 'Illusion',
    'N': 'Necromancy',
    'T': 'Transmutation'
};

// Item type abbreviation mapping (Fight Club 5e XML format)
const ITEM_TYPE_MAP: { [key: string]: { type: string; subtype?: string } } = {
    'M': { type: 'Weapon', subtype: 'Melee Weapon' },
    'R': { type: 'Weapon', subtype: 'Ranged Weapon' },
    'A': { type: 'Ammunition' },
    'LA': { type: 'Armor', subtype: 'Light Armor' },
    'MA': { type: 'Armor', subtype: 'Medium Armor' },
    'HA': { type: 'Armor', subtype: 'Heavy Armor' },
    'S': { type: 'Armor', subtype: 'Shield' },
    'W': { type: 'Wondrous Item' },
    'WD': { type: 'Wand' },
    'RD': { type: 'Rod' },
    'ST': { type: 'Staff' },
    'RG': { type: 'Ring' },
    'P': { type: 'Potion' },
    'SC': { type: 'Scroll' },
    'G': { type: 'Adventuring Gear' },
    '$': { type: 'Adventuring Gear', subtype: 'Currency/Trade Good' },
};

// Damage type abbreviation mapping (Fight Club 5e XML format)
const DAMAGE_TYPE_MAP: { [key: string]: string } = {
    // Standard single-letter abbreviations
    'S': 'slashing',
    'P': 'piercing',
    'B': 'bludgeoning',
    'A': 'acid',
    'C': 'cold',
    'F': 'fire',
    'L': 'lightning',
    'N': 'necrotic',
    'R': 'radiant',
    'T': 'thunder',
    // Multi-letter abbreviations found in compendiums
    'FC': 'force',
    'PS': 'psychic',
    'PY': 'psychic',
    // Additional potential abbreviations
    'O': 'force',
    'I': 'poison',
    'Y': 'psychic',
};

// Weapon property abbreviation mapping
const PROPERTY_MAP: { [key: string]: string } = {
    'A': 'Ammunition',
    'F': 'Finesse',
    'H': 'Heavy',
    'L': 'Light',
    'LD': 'Loading',
    'R': 'Reach',
    'S': 'Special',
    'T': 'Thrown',
    '2H': 'Two-Handed',
    'V': 'Versatile',
    'M': 'Monk',
};

/**
 * Represents a custom spell from a .dndspell file.
 * Uses a slightly different format than the Spell interface.
 */
export interface CustomSpell {
    name: string;
    level: number;
    school: string;
    castingTime: string;
    range: string;
    duration: string;
    componentV: boolean;
    componentS: boolean;
    componentM: boolean;
    materials?: string;
    ritual: boolean;
    concentration: boolean;
    classes: string;
    description: string;
    higherLevels?: string;
    filePath?: string; // Track the source file
}

/**
 * Represents a custom weapon from a .dnditem file with type "Weapon".
 */
export interface CustomWeapon {
    name: string;
    type: string;
    subtype?: string;
    rarity: string;
    magic: boolean;
    attunement: boolean;
    attunementRequirement?: string;
    weight: number;
    value: string;
    damage?: {
        dice: string;
        type: string;
        twoHanded?: string;
    };
    properties: string[];
    range?: {
        normal: number;
        long?: number;
    };
    description: string;
    filePath?: string; // Track the source file
}

export class CompendiumService {
    private static instance: CompendiumService;
    private spells: Map<string, Spell> = new Map();
    private monsters: Map<string, Monster> = new Map();
    private items: Map<string, Item> = new Map();
    private customSpells: Map<string, CustomSpell> = new Map();
    private customWeapons: Map<string, CustomWeapon> = new Map();
    private initialized: boolean = false;
    private context: vscode.ExtensionContext;
    private customSpellWatcher: vscode.FileSystemWatcher | undefined;
    private customItemWatcher: vscode.FileSystemWatcher | undefined;

    private constructor(context: vscode.ExtensionContext) {
        this.context = context;
    }

    public static getInstance(context?: vscode.ExtensionContext): CompendiumService {
        if (!CompendiumService.instance) {
            if (!context) {
                throw new Error('CompendiumService must be initialized with context first');
            }
            CompendiumService.instance = new CompendiumService(context);
        }
        return CompendiumService.instance;
    }

    public async initialize(): Promise<void> {
        if (this.initialized) {
            return;
        }

        // Load bundled SRD data first
        await this.loadSrdData();

        // Check for user-imported compendium
        const config = vscode.workspace.getConfiguration('dnd.compendium');
        const importedPath = config.get<string>('importedPath');

        if (importedPath) {
            const importedUri = vscode.Uri.file(importedPath);
            if (await this.fileExists(importedUri)) {
                await this.importXmlCompendium(importedUri);
            }
        }

        // Load custom spells from workspace
        await this.loadCustomSpells();

        // Load custom weapons from workspace
        await this.loadCustomWeapons();

        // Set up file watcher for custom spells
        this.setupCustomSpellWatcher();

        // Set up file watcher for custom items (weapons)
        this.setupCustomItemWatcher();

        this.initialized = true;
    }

    /**
     * Load all custom .dndspell files from the workspace.
     */
    private async loadCustomSpells(): Promise<void> {
        this.customSpells.clear();

        const workspaceFolders = vscode.workspace.workspaceFolders;
        if (!workspaceFolders) {
            return;
        }

        try {
            const files = await vscode.workspace.findFiles('**/*.dndspell', '**/node_modules/**');
            for (const file of files) {
                await this.loadCustomSpellFile(file);
            }
        } catch (error) {
            console.error('Error loading custom spells:', error);
        }
    }

    /**
     * Load a single custom spell file.
     */
    private async loadCustomSpellFile(uri: vscode.Uri): Promise<void> {
        try {
            const content = await vscode.workspace.fs.readFile(uri);
            const text = new TextDecoder().decode(content);
            const data = JSON.parse(text) as CustomSpell;

            if (data.name) {
                data.filePath = uri.fsPath;
                this.customSpells.set(data.name.toLowerCase(), data);
            }
        } catch (error) {
            console.error(`Error loading custom spell from ${uri.fsPath}:`, error);
        }
    }

    /**
     * Set up a file watcher to reload custom spells when they change.
     */
    private setupCustomSpellWatcher(): void {
        if (this.customSpellWatcher) {
            this.customSpellWatcher.dispose();
        }

        this.customSpellWatcher = vscode.workspace.createFileSystemWatcher('**/*.dndspell');

        this.customSpellWatcher.onDidCreate(async (uri) => {
            await this.loadCustomSpellFile(uri);
        });

        this.customSpellWatcher.onDidChange(async (uri) => {
            await this.loadCustomSpellFile(uri);
        });

        this.customSpellWatcher.onDidDelete((uri) => {
            // Find and remove the spell that was in this file
            for (const [key, spell] of this.customSpells) {
                if (spell.filePath === uri.fsPath) {
                    this.customSpells.delete(key);
                    break;
                }
            }
        });
    }

    /**
     * Load all custom .dnditem weapon files from the workspace.
     */
    private async loadCustomWeapons(): Promise<void> {
        this.customWeapons.clear();

        const workspaceFolders = vscode.workspace.workspaceFolders;
        if (!workspaceFolders) {
            return;
        }

        try {
            const files = await vscode.workspace.findFiles('**/*.dnditem', '**/node_modules/**');
            for (const file of files) {
                await this.loadCustomWeaponFile(file);
            }
        } catch (error) {
            console.error('Error loading custom weapons:', error);
        }
    }

    /**
     * Load a single custom item file if it's a weapon.
     */
    private async loadCustomWeaponFile(uri: vscode.Uri): Promise<void> {
        try {
            const content = await vscode.workspace.fs.readFile(uri);
            const text = new TextDecoder().decode(content);
            const data = JSON.parse(text);

            // Only load items of type "Weapon"
            if (data.name && data.type === 'Weapon') {
                const weapon: CustomWeapon = {
                    name: data.name,
                    type: data.type,
                    subtype: data.subtype,
                    rarity: data.rarity || 'Common',
                    magic: data.magic || false,
                    attunement: data.attunement || false,
                    attunementRequirement: data.attunementRequirement,
                    weight: data.weight || 0,
                    value: data.value || '',
                    damage: data.damage,
                    properties: data.properties || [],
                    range: data.range,
                    description: data.description || '',
                    filePath: uri.fsPath
                };
                this.customWeapons.set(data.name.toLowerCase(), weapon);
            }
        } catch (error) {
            console.error(`Error loading custom weapon from ${uri.fsPath}:`, error);
        }
    }

    /**
     * Set up a file watcher to reload custom items when they change.
     */
    private setupCustomItemWatcher(): void {
        if (this.customItemWatcher) {
            this.customItemWatcher.dispose();
        }

        this.customItemWatcher = vscode.workspace.createFileSystemWatcher('**/*.dnditem');

        this.customItemWatcher.onDidCreate(async (uri) => {
            await this.loadCustomWeaponFile(uri);
        });

        this.customItemWatcher.onDidChange(async (uri) => {
            await this.loadCustomWeaponFile(uri);
        });

        this.customItemWatcher.onDidDelete((uri) => {
            // Find and remove the weapon that was in this file
            for (const [key, weapon] of this.customWeapons) {
                if (weapon.filePath === uri.fsPath) {
                    this.customWeapons.delete(key);
                    break;
                }
            }
        });
    }

    /**
     * Convert a CustomSpell to the standard Spell format for display.
     */
    private customSpellToSpell(custom: CustomSpell): Spell {
        // Build components string
        const components: string[] = [];
        if (custom.componentV) components.push('V');
        if (custom.componentS) components.push('S');
        if (custom.componentM) {
            components.push(custom.materials ? `M (${custom.materials})` : 'M');
        }

        // Parse classes string to array
        const classes = custom.classes
            ? custom.classes.split(',').map(c => c.trim()).filter(c => c)
            : [];

        return {
            name: custom.name,
            level: custom.level,
            school: custom.school,
            castingTime: custom.castingTime,
            range: custom.range,
            components: components.join(', '),
            duration: custom.duration,
            description: custom.description,
            higherLevels: custom.higherLevels,
            classes,
            ritual: custom.ritual,
            concentration: custom.concentration,
            source: 'Custom'
        };
    }

    private async loadSrdData(): Promise<void> {
        try {
            // Load bundled SRD spells
            const srdSpellsUri = vscode.Uri.joinPath(this.context.extensionUri, 'src', 'data', 'srd-spells.json');
            if (await this.fileExists(srdSpellsUri)) {
                const content = await vscode.workspace.fs.readFile(srdSpellsUri);
                const data = JSON.parse(new TextDecoder().decode(content));
                for (const spell of data.spells || []) {
                    this.spells.set(spell.name.toLowerCase(), spell);
                }
            }

            // Load bundled SRD items
            const srdItemsUri = vscode.Uri.joinPath(this.context.extensionUri, 'src', 'data', 'srd-items.json');
            if (await this.fileExists(srdItemsUri)) {
                const content = await vscode.workspace.fs.readFile(srdItemsUri);
                const data = JSON.parse(new TextDecoder().decode(content));
                for (const item of data.items || []) {
                    this.items.set(item.name.toLowerCase(), item);
                }
            }

            // Load bundled SRD monsters
            const srdMonstersUri = vscode.Uri.joinPath(this.context.extensionUri, 'src', 'data', 'srd-monsters.json');
            if (await this.fileExists(srdMonstersUri)) {
                const content = await vscode.workspace.fs.readFile(srdMonstersUri);
                const data = JSON.parse(new TextDecoder().decode(content));
                for (const monster of data.monsters || []) {
                    this.monsters.set(monster.name.toLowerCase(), monster);
                }
            }
        } catch (error) {
            console.error('Error loading SRD data:', error);
        }
    }

    private async fileExists(uri: vscode.Uri): Promise<boolean> {
        try {
            await vscode.workspace.fs.stat(uri);
            return true;
        } catch {
            return false;
        }
    }

    public async importXmlCompendium(fileUri: vscode.Uri): Promise<{ spells: number; monsters: number; items: number }> {
        const counts = { spells: 0, monsters: 0, items: 0 };

        try {
            const contentBytes = await vscode.workspace.fs.readFile(fileUri);
            const content = new TextDecoder().decode(contentBytes);

            // Parse spells (don't overwrite SRD spells which have better data)
            const spellMatches = content.matchAll(/<spell>([\s\S]*?)<\/spell>/g);
            for (const match of spellMatches) {
                const spell = this.parseXmlSpell(match[1]);
                if (spell && spell.name && !this.spells.has(spell.name.toLowerCase())) {
                    this.spells.set(spell.name.toLowerCase(), spell);
                    counts.spells++;
                }
            }

            // Parse monsters (don't overwrite SRD monsters which have better data)
            const monsterMatches = content.matchAll(/<monster>([\s\S]*?)<\/monster>/g);
            for (const match of monsterMatches) {
                const monster = this.parseXmlMonster(match[1]);
                if (monster && monster.name && !this.monsters.has(monster.name.toLowerCase())) {
                    this.monsters.set(monster.name.toLowerCase(), monster);
                    counts.monsters++;
                }
            }

            // Parse items (don't overwrite SRD items which have better data)
            const itemMatches = content.matchAll(/<item>([\s\S]*?)<\/item>/g);
            for (const match of itemMatches) {
                const item = this.parseXmlItem(match[1]);
                if (item && item.name && !this.items.has(item.name.toLowerCase())) {
                    this.items.set(item.name.toLowerCase(), item);
                    counts.items++;
                }
            }
        } catch (error) {
            console.error('Error importing XML compendium:', error);
            vscode.window.showErrorMessage(`Failed to import compendium: ${error}`);
        }

        return counts;
    }

    /**
     * Extract content from an XML tag.
     */
    private getXmlTag(xml: string, tag: string): string {
        const match = xml.match(new RegExp(`<${tag}>([\\s\\S]*?)<\\/${tag}>`));
        return match ? match[1].trim() : '';
    }

    private parseXmlSpell(xml: string): Spell | null {
        const getTag = (tag: string): string => this.getXmlTag(xml, tag);

        const name = getTag('name');
        if (!name || name.startsWith('Invocation:')) {
            return null; // Skip invocations and empty entries
        }

        const levelStr = getTag('level');
        const level = parseInt(levelStr) || 0;
        const schoolAbbr = getTag('school');
        const school = SCHOOL_MAP[schoolAbbr] || schoolAbbr || 'Unknown';

        const text = getTag('text');
        const lines = text.split('\n').map(l => l.trim()).filter(l => l);

        // Extract higher levels text if present
        let description = '';
        let higherLevels = '';

        for (const line of lines) {
            if (line.startsWith('At Higher Levels:')) {
                higherLevels = line.replace('At Higher Levels:', '').trim();
            } else if (!line.startsWith('Source:')) {
                description += (description ? '\n' : '') + line;
            }
        }

        // Extract source
        const sourceMatch = text.match(/Source:\s*(.+?)(?:\n|$)/);
        const source = sourceMatch ? sourceMatch[1].trim() : 'Unknown';

        // Parse classes
        const classesStr = getTag('classes');
        const classes = classesStr.split(',').map(c => c.trim()).filter(c => c && !c.includes('('));

        // Check for concentration and ritual
        const duration = getTag('duration');
        const concentration = duration.toLowerCase().includes('concentration');
        const ritual = xml.includes('<ritual>YES</ritual>');

        // Parse damage if present
        let damage: Spell['damage'] | undefined;
        const rollMatches = xml.matchAll(/<roll description="([^"]*)"(?: level="(\d+)")?>([\dd+]+)<\/roll>/g);
        const damageRolls: { [level: number]: string } = {};
        let damageType = '';

        for (const rollMatch of rollMatches) {
            const desc = rollMatch[1];
            const lvl = rollMatch[2] ? parseInt(rollMatch[2]) : level;
            const dice = rollMatch[3];

            if (desc.toLowerCase().includes('damage')) {
                damageRolls[lvl] = dice;
                if (!damageType) {
                    // Extract damage type from description (e.g., "Fire Damage" -> "fire")
                    damageType = desc.replace(/damage/i, '').trim().toLowerCase();
                }
            }
        }

        if (Object.keys(damageRolls).length > 0) {
            damage = { type: damageType, dice: damageRolls };
        }

        return {
            name,
            level,
            school,
            castingTime: getTag('time') || '1 action',
            range: getTag('range') || 'Self',
            components: getTag('components') || '',
            duration: duration || 'Instantaneous',
            description,
            higherLevels: higherLevels || undefined,
            classes,
            ritual,
            concentration,
            source,
            damage
        };
    }

    private parseXmlMonster(xml: string): Monster | null {
        const getTag = (tag: string): string => this.getXmlTag(xml, tag);

        const name = getTag('name');
        if (!name) {
            return null;
        }

        const cr = getTag('cr') || '0';

        // Parse HP - may be in format "22 (3d8+9)" or just "22"
        const hpStr = getTag('hp') || '1';
        const hpMatch = hpStr.match(/^(\d+)/);
        const hp = hpMatch ? parseInt(hpMatch[1]) : 1;

        // Extract hit dice from HP string if present, otherwise use <hd> tag
        const hdMatch = hpStr.match(/\(([^)]+)\)/);
        const hitDice = hdMatch ? hdMatch[1] : (getTag('hd') || '1d8');

        // Parse type - may include subtype in format "humanoid (human)"
        const typeStr = getTag('type') || 'unknown';
        const typeMatch = typeStr.match(/^([^(]+)(?:\s*\(([^)]+)\))?/);
        const type = typeMatch ? typeMatch[1].trim() : typeStr;
        const subtype = typeMatch && typeMatch[2] ? typeMatch[2].trim() : undefined;

        // Parse saves - format: "Int +5, Wis +3"
        const saveStr = getTag('save');
        const saves = saveStr ? saveStr.split(',').map(s => s.trim()).filter(s => s) : undefined;

        // Parse skills - format: "Arcana +5, History +5"
        const skillStr = getTag('skill');
        const skills = skillStr ? skillStr.split(',').map(s => s.trim()).filter(s => s) : undefined;

        // Parse damage vulnerabilities, resistances, immunities
        const vulnerableStr = getTag('vulnerable');
        const damageVulnerabilities = vulnerableStr ? vulnerableStr.split(',').map(s => s.trim()).filter(s => s) : undefined;

        const resistStr = getTag('resist');
        const damageResistances = resistStr ? resistStr.split(',').map(s => s.trim()).filter(s => s) : undefined;

        const immuneStr = getTag('immune');
        const damageImmunities = immuneStr ? immuneStr.split(',').map(s => s.trim()).filter(s => s) : undefined;

        // Parse condition immunities
        const conditionImmuneStr = getTag('conditionImmune');
        const conditionImmunities = conditionImmuneStr ? conditionImmuneStr.split(',').map(s => s.trim()).filter(s => s) : undefined;

        // Parse senses and passive perception
        const sensesStr = getTag('senses') || '';
        const passiveStr = getTag('passive') || '10';
        const senses = sensesStr
            ? `${sensesStr}, passive Perception ${passiveStr}`
            : `passive Perception ${passiveStr}`;

        // Parse traits
        const traits = this.parseXmlFeatures(xml, 'trait');

        // Parse actions
        const actions = this.parseXmlFeatures(xml, 'action');

        // Parse reactions
        const reactions = this.parseXmlFeatures(xml, 'reaction');

        // Parse legendary actions
        const legendaryActions = this.parseXmlFeatures(xml, 'legendary');

        return {
            name,
            size: getTag('size') || 'M',
            type,
            subtype,
            alignment: getTag('alignment') || 'unaligned',
            ac: parseInt(getTag('ac')) || 10,
            hp,
            hitDice,
            speed: getTag('speed') || '30 ft.',
            stats: {
                str: parseInt(getTag('str')) || 10,
                dex: parseInt(getTag('dex')) || 10,
                con: parseInt(getTag('con')) || 10,
                int: parseInt(getTag('int')) || 10,
                wis: parseInt(getTag('wis')) || 10,
                cha: parseInt(getTag('cha')) || 10
            },
            saves: saves?.length ? saves : undefined,
            skills: skills?.length ? skills : undefined,
            damageVulnerabilities: damageVulnerabilities?.length ? damageVulnerabilities : undefined,
            damageResistances: damageResistances?.length ? damageResistances : undefined,
            damageImmunities: damageImmunities?.length ? damageImmunities : undefined,
            conditionImmunities: conditionImmunities?.length ? conditionImmunities : undefined,
            senses,
            languages: getTag('languages') || 'None',
            cr,
            xp: this.crToXp(cr),
            proficiencyBonus: this.crToProficiency(cr),
            traits: traits.length ? traits : undefined,
            actions: actions.length ? actions : undefined,
            reactions: reactions.length ? reactions : undefined,
            legendaryActions: legendaryActions.length ? legendaryActions : undefined,
            description: getTag('description') || undefined,
            source: 'Imported Compendium'
        };
    }

    private parseXmlFeatures(xml: string, tagName: string): Array<{ name: string; description: string }> {
        const features: Array<{ name: string; description: string }> = [];
        const regex = new RegExp(`<${tagName}>([\\s\\S]*?)<\\/${tagName}>`, 'g');
        let match;

        while ((match = regex.exec(xml)) !== null) {
            const featureXml = match[1];
            const name = this.getXmlTag(featureXml, 'name');
            const text = this.getXmlTag(featureXml, 'text');

            if (name && text) {
                features.push({ name, description: text });
            }
        }

        return features;
    }

    private crToXp(cr: string): number {
        const xpMap: { [key: string]: number } = {
            '0': 0, '1/8': 25, '1/4': 50, '1/2': 100,
            '1': 200, '2': 450, '3': 700, '4': 1100, '5': 1800,
            '6': 2300, '7': 2900, '8': 3900, '9': 5000, '10': 5900,
            '11': 7200, '12': 8400, '13': 10000, '14': 11500, '15': 13000,
            '16': 15000, '17': 18000, '18': 20000, '19': 22000, '20': 25000,
            '21': 33000, '22': 41000, '23': 50000, '24': 62000, '25': 75000,
            '26': 90000, '27': 105000, '28': 120000, '29': 135000, '30': 155000
        };
        return xpMap[cr] || 0;
    }

    private crToProficiency(cr: string): number {
        const numCr = cr.includes('/') ? eval(cr) : parseFloat(cr);
        if (numCr < 5) return 2;
        if (numCr < 9) return 3;
        if (numCr < 13) return 4;
        if (numCr < 17) return 5;
        if (numCr < 21) return 6;
        if (numCr < 25) return 7;
        if (numCr < 29) return 8;
        return 9;
    }

    private parseXmlItem(xml: string): Item | null {
        const getTag = (tag: string): string => this.getXmlTag(xml, tag);

        const name = getTag('name');
        if (!name) {
            return null;
        }

        const detail = getTag('detail');
        const attunement = detail.toLowerCase().includes('requires attunement');

        // Extract attunement requirement if present
        let attunementRequirement: string | undefined;
        const attunementMatch = detail.match(/requires attunement(?: by (?:a |an )?([^,)]+))?/i);
        if (attunementMatch && attunementMatch[1]) {
            attunementRequirement = attunementMatch[1].trim();
        }

        // Parse rarity from detail string
        const rarityMatch = detail.match(/\b(common|uncommon|rare|very rare|legendary|artifact)\b/i);
        const rarity = rarityMatch ? rarityMatch[1].charAt(0).toUpperCase() + rarityMatch[1].slice(1).toLowerCase() : 'Common';

        // Parse weight
        const weightStr = getTag('weight');
        const weight = parseFloat(weightStr) || 0;

        // Parse value
        const value = getTag('value') || '';

        // Determine if magic item
        const magic = rarity !== 'Common' || detail.toLowerCase().includes('magic');

        // Parse properties and map abbreviations to full names
        const propertyStr = getTag('property');
        const properties = propertyStr
            ? propertyStr.split(',').map(p => p.trim()).filter(p => p).map(p => PROPERTY_MAP[p] || p)
            : [];

        // Parse damage if present, mapping type abbreviation
        const dmgStr = getTag('dmg1');
        const dmgTypeRaw = getTag('dmgType');
        const dmgType = DAMAGE_TYPE_MAP[dmgTypeRaw] || dmgTypeRaw;
        const dmg2Str = getTag('dmg2');

        let damage: Item['damage'] | undefined;
        if (dmgStr) {
            // Standard damage tags present
            damage = {
                dice: dmgStr,
                type: dmgType || '',
                twoHanded: dmg2Str || undefined
            };
        } else {
            // Try to extract damage from <roll> tags if no dmg1 tag
            // Look for roll tags with "damage" in description
            const rollMatch = xml.match(/<roll description="([^"]*[Dd]amage[^"]*)">([\dd+]+)<\/roll>/);
            if (rollMatch) {
                const rollDesc = rollMatch[1].toLowerCase();
                const rollDice = rollMatch[2];
                // Extract damage type from description (e.g., "Fire Damage" -> "fire")
                let rollDamageType = '';
                for (const fullType of Object.values(DAMAGE_TYPE_MAP)) {
                    if (rollDesc.includes(fullType)) {
                        rollDamageType = fullType;
                        break;
                    }
                }
                // Also check for full type names directly
                const typeMatch = rollDesc.match(/(slashing|piercing|bludgeoning|fire|cold|lightning|thunder|poison|acid|necrotic|radiant|force|psychic)/i);
                if (typeMatch) {
                    rollDamageType = typeMatch[1].toLowerCase();
                }
                damage = {
                    dice: rollDice,
                    type: rollDamageType,
                    twoHanded: undefined
                };
            }
        }

        // Parse AC if present
        const acStr = getTag('ac');
        const armorClass = acStr ? {
            base: parseInt(acStr) || 0,
            dexBonus: !detail.toLowerCase().includes('heavy'),
            maxBonus: detail.toLowerCase().includes('medium') ? 2 : undefined
        } : undefined;

        // Parse stealth disadvantage
        const stealthStr = getTag('stealth');
        const stealthDisadvantage = stealthStr.toLowerCase() === 'yes';

        // Parse strength requirement
        const strengthStr = getTag('strength');
        const strengthRequirement = strengthStr ? parseInt(strengthStr) : undefined;

        // Parse range if present
        const rangeStr = getTag('range');
        let range: Item['range'] | undefined;
        if (rangeStr) {
            const rangeMatch = rangeStr.match(/(\d+)(?:\/(\d+))?/);
            if (rangeMatch) {
                range = {
                    normal: parseInt(rangeMatch[1]),
                    long: rangeMatch[2] ? parseInt(rangeMatch[2]) : undefined
                };
            }
        }

        // Map XML type abbreviation to proper type/subtype
        const xmlType = getTag('type');
        const typeInfo = ITEM_TYPE_MAP[xmlType] || { type: xmlType || 'Adventuring Gear' };

        return {
            name,
            type: typeInfo.type,
            subtype: typeInfo.subtype,
            rarity,
            magic,
            attunement,
            attunementRequirement,
            weight,
            value,
            damage,
            armorClass,
            stealthDisadvantage: stealthDisadvantage || undefined,
            strengthRequirement,
            properties,
            range,
            description: getTag('text') || '',
            source: 'Imported Compendium'
        };
    }

    // Public API methods
    public getSpell(name: string): Spell | undefined {
        const lowerName = name.toLowerCase();

        // Check custom spells first (user spells take priority)
        const customSpell = this.customSpells.get(lowerName);
        if (customSpell) {
            return this.customSpellToSpell(customSpell);
        }

        return this.spells.get(lowerName);
    }

    /**
     * Get a custom spell by name (returns the raw CustomSpell format).
     */
    public getCustomSpell(name: string): CustomSpell | undefined {
        return this.customSpells.get(name.toLowerCase());
    }

    /**
     * Check if a spell is a custom spell from a .dndspell file.
     */
    public isCustomSpell(name: string): boolean {
        return this.customSpells.has(name.toLowerCase());
    }

    public searchSpells(query: string, limit: number = 20): Spell[] {
        const results: Spell[] = [];
        const lowerQuery = query.toLowerCase();
        const addedNames = new Set<string>();

        // Search custom spells first (they take priority)
        for (const [key, customSpell] of this.customSpells) {
            if (key.includes(lowerQuery) || customSpell.name.toLowerCase().includes(lowerQuery)) {
                results.push(this.customSpellToSpell(customSpell));
                addedNames.add(key);
                if (results.length >= limit) {
                    break;
                }
            }
        }

        // Then search SRD/compendium spells
        if (results.length < limit) {
            for (const [key, spell] of this.spells) {
                // Skip if already added from custom spells
                if (addedNames.has(key)) {
                    continue;
                }
                if (key.includes(lowerQuery) || spell.name.toLowerCase().includes(lowerQuery)) {
                    results.push(spell);
                    if (results.length >= limit) {
                        break;
                    }
                }
            }
        }

        return results.sort((a, b) => {
            // Prioritize custom spells
            const aIsCustom = a.source === 'Custom';
            const bIsCustom = b.source === 'Custom';
            if (aIsCustom && !bIsCustom) return -1;
            if (!aIsCustom && bIsCustom) return 1;

            // Then prioritize exact prefix matches
            const aStartsWith = a.name.toLowerCase().startsWith(lowerQuery);
            const bStartsWith = b.name.toLowerCase().startsWith(lowerQuery);
            if (aStartsWith && !bStartsWith) return -1;
            if (!aStartsWith && bStartsWith) return 1;
            return a.name.localeCompare(b.name);
        });
    }

    public getMonster(name: string): Monster | undefined {
        return this.monsters.get(name.toLowerCase());
    }

    public searchMonsters(query: string, limit: number = 20): Monster[] {
        const results: Monster[] = [];
        const lowerQuery = query.toLowerCase();

        for (const [key, monster] of this.monsters) {
            if (key.includes(lowerQuery)) {
                results.push(monster);
                if (results.length >= limit) {
                    break;
                }
            }
        }

        return results.sort((a, b) => a.name.localeCompare(b.name));
    }

    public getItem(name: string): Item | undefined {
        return this.items.get(name.toLowerCase());
    }

    public searchItems(query: string, limit: number = 20): Item[] {
        const results: Item[] = [];
        const lowerQuery = query.toLowerCase();

        for (const [key, item] of this.items) {
            if (key.includes(lowerQuery)) {
                results.push(item);
                if (results.length >= limit) {
                    break;
                }
            }
        }

        return results.sort((a, b) => a.name.localeCompare(b.name));
    }

    /**
     * Get a weapon by name (checks custom weapons first, then compendium items).
     */
    public getWeapon(name: string): Item | undefined {
        const lowerName = name.toLowerCase();

        // Check custom weapons first (user weapons take priority)
        const customWeapon = this.customWeapons.get(lowerName);
        if (customWeapon) {
            return this.customWeaponToItem(customWeapon);
        }

        // Check compendium items for weapons
        const item = this.items.get(lowerName);
        if (item && item.type === 'Weapon') {
            return item;
        }

        return undefined;
    }

    /**
     * Check if a weapon is a custom weapon from a .dnditem file.
     */
    public isCustomWeapon(name: string): boolean {
        return this.customWeapons.has(name.toLowerCase());
    }

    /**
     * Convert a CustomWeapon to the standard Item format for display.
     */
    private customWeaponToItem(custom: CustomWeapon): Item {
        return {
            name: custom.name,
            type: custom.type,
            subtype: custom.subtype,
            rarity: custom.rarity,
            magic: custom.magic,
            attunement: custom.attunement,
            attunementRequirement: custom.attunementRequirement,
            weight: custom.weight,
            value: custom.value,
            damage: custom.damage,
            properties: custom.properties,
            range: custom.range,
            description: custom.description,
            source: 'Custom'
        };
    }

    /**
     * Search for weapons (both custom and compendium).
     */
    public searchWeapons(query: string, limit: number = 20): Item[] {
        const results: Item[] = [];
        const lowerQuery = query.toLowerCase();
        const addedNames = new Set<string>();

        // Search custom weapons first (they take priority)
        for (const [key, customWeapon] of this.customWeapons) {
            if (key.includes(lowerQuery) || customWeapon.name.toLowerCase().includes(lowerQuery)) {
                results.push(this.customWeaponToItem(customWeapon));
                addedNames.add(key);
                if (results.length >= limit) {
                    break;
                }
            }
        }

        // Then search compendium items for weapons
        if (results.length < limit) {
            for (const [key, item] of this.items) {
                // Only include weapons
                if (item.type !== 'Weapon') {
                    continue;
                }
                // Skip if already added from custom weapons
                if (addedNames.has(key)) {
                    continue;
                }
                if (key.includes(lowerQuery) || item.name.toLowerCase().includes(lowerQuery)) {
                    results.push(item);
                    if (results.length >= limit) {
                        break;
                    }
                }
            }
        }

        return results.sort((a, b) => {
            // Prioritize custom weapons
            const aIsCustom = a.source === 'Custom';
            const bIsCustom = b.source === 'Custom';
            if (aIsCustom && !bIsCustom) return -1;
            if (!aIsCustom && bIsCustom) return 1;

            // Then prioritize exact prefix matches
            const aStartsWith = a.name.toLowerCase().startsWith(lowerQuery);
            const bStartsWith = b.name.toLowerCase().startsWith(lowerQuery);
            if (aStartsWith && !bStartsWith) return -1;
            if (!aStartsWith && bStartsWith) return 1;
            return a.name.localeCompare(b.name);
        });
    }

    /**
     * Get full weapon info formatted for webview display.
     */
    public getWeaponInfo(name: string): {
        name: string;
        type: string;
        subtype?: string;
        rarity: string;
        magic: boolean;
        damage?: Item['damage'];
        properties: string[];
        range?: Item['range'];
        description: string;
        isCustom: boolean;
        filePath?: string;
    } | null {
        const weapon = this.getWeapon(name);
        if (!weapon) {
            return null;
        }

        const isCustom = this.isCustomWeapon(name);
        const customWeapon = isCustom ? this.customWeapons.get(name.toLowerCase()) : undefined;

        return {
            name: weapon.name,
            type: weapon.type,
            subtype: weapon.subtype,
            rarity: weapon.rarity,
            magic: weapon.magic,
            damage: weapon.damage,
            properties: weapon.properties,
            range: weapon.range,
            description: weapon.description,
            isCustom,
            filePath: customWeapon?.filePath
        };
    }

    public getStats(): { spells: number; monsters: number; items: number; customSpells: number } {
        return {
            spells: this.spells.size,
            monsters: this.monsters.size,
            items: this.items.size,
            customSpells: this.customSpells.size
        };
    }

    // Format spell for compact display (autocomplete, etc.)
    public formatSpellCompact(spell: Spell): string {
        const levelText = spell.level === 0 ? 'Cantrip' : `Level ${spell.level}`;
        return `${spell.name} (${levelText} ${spell.school})`;
    }

    /**
     * Format a spell as a search result for UI display.
     */
    public formatSpellSearchResult(spell: Spell): CompendiumSearchResult {
        return {
            type: 'spell',
            name: spell.name,
            subtitle: `${spell.level === 0 ? 'Cantrip' : 'Level ' + spell.level} ${spell.school}`,
            isCustom: spell.source === 'Custom'
        };
    }

    /**
     * Format a monster as a search result for UI display.
     */
    public formatMonsterSearchResult(monster: Monster): CompendiumSearchResult {
        return {
            type: 'monster',
            name: monster.name,
            subtitle: `${monster.type} - CR ${monster.cr}`
        };
    }

    /**
     * Format an item as a search result for UI display.
     */
    public formatItemSearchResult(item: Item): CompendiumSearchResult {
        const parts = [item.subtype || item.type];
        if (item.magic && item.rarity !== 'Common') {
            parts.push(item.rarity);
        }
        return {
            type: 'item',
            name: item.name,
            subtitle: parts.join(' - ')
        };
    }

    // Format item for compact display (autocomplete, etc.)
    public formatItemCompact(item: Item): string {
        const parts = [item.name];
        if (item.subtype) {
            parts.push(`(${item.subtype})`);
        } else {
            parts.push(`(${item.type})`);
        }
        if (item.magic && item.rarity !== 'Common') {
            parts.push(`- ${item.rarity}`);
        }
        return parts.join(' ');
    }

    /**
     * Search all compendium entries and return formatted results.
     */
    public searchAll(query: string, searchType: 'spell' | 'monster' | 'item' | 'all' = 'all', limit: number = 5): CompendiumSearchResult[] {
        let results: CompendiumSearchResult[] = [];

        if (searchType === 'spell' || searchType === 'all') {
            const spells = this.searchSpells(query, limit).map(s => this.formatSpellSearchResult(s));
            results = results.concat(spells);
        }
        if (searchType === 'monster' || searchType === 'all') {
            const monsters = this.searchMonsters(query, limit).map(m => this.formatMonsterSearchResult(m));
            results = results.concat(monsters);
        }
        if (searchType === 'item' || searchType === 'all') {
            const items = this.searchItems(query, limit).map(i => this.formatItemSearchResult(i));
            results = results.concat(items);
        }

        return results;
    }

    /**
     * Get full spell info formatted for webview display.
     */
    public getSpellInfo(name: string): {
        name: string;
        level: number;
        school: string;
        castingTime: string;
        range: string;
        components: string;
        duration: string;
        description: string;
        higherLevels?: string;
        concentration: boolean;
        ritual: boolean;
        damage?: Spell['damage'];
        classes: string[];
        isCustom: boolean;
        filePath?: string;
    } | null {
        const spell = this.getSpell(name);
        if (!spell) {
            return null;
        }

        const isCustom = this.isCustomSpell(name);
        const customSpell = isCustom ? this.getCustomSpell(name) : undefined;

        return {
            name: spell.name,
            level: spell.level,
            school: spell.school,
            castingTime: spell.castingTime,
            range: spell.range,
            components: spell.components,
            duration: spell.duration,
            description: spell.description,
            higherLevels: spell.higherLevels,
            concentration: spell.concentration,
            ritual: spell.ritual,
            damage: spell.damage,
            classes: spell.classes,
            isCustom,
            filePath: customSpell?.filePath
        };
    }

    /**
     * Get full item info formatted for webview display.
     */
    public getItemInfo(name: string): {
        name: string;
        type: string;
        subtype?: string;
        rarity: string;
        magic: boolean;
        attunement: boolean;
        attunementRequirement?: string;
        weight: number;
        value: string;
        damage?: Item['damage'];
        armorClass?: Item['armorClass'];
        properties: string[];
        range?: Item['range'];
        description: string;
    } | null {
        const item = this.getItem(name);
        if (!item) {
            return null;
        }
        return {
            name: item.name,
            type: item.type,
            subtype: item.subtype,
            rarity: item.rarity,
            magic: item.magic,
            attunement: item.attunement,
            attunementRequirement: item.attunementRequirement,
            weight: item.weight,
            value: item.value,
            damage: item.damage,
            armorClass: item.armorClass,
            properties: item.properties,
            range: item.range,
            description: item.description
        };
    }

    /**
     * Get full monster info formatted for webview display.
     */
    public getMonsterInfo(name: string): Monster | null {
        return this.getMonster(name) || null;
    }
}
